/**
 * Shared collapsible-section chrome used by every block on
 * RolevayaSettingsPage (Дары, Теги, Игроки и ID, ...). Pulled out of the old
 * monolithic content() method so each section's own file only has to render
 * its inner content.
 */
export function Section(iconClass, title, description, content) {
  return m("section", {
    className: "RolevayaAdminSection"
  }, m("div", {
    className: "RolevayaAdminSection-header"
  }, m("div", {
    className: "RolevayaAdminSection-titleWrap"
  }, m("div", {
    className: "RolevayaAdminSection-icon"
  }, m("i", {
    className: iconClass,
    "aria-hidden": "true"
  })), m("div", {
    className: "RolevayaAdminSection-titleText"
  }, m("h3", null, title), m("p", null, description)))), m("div", {
    className: "RolevayaAdminSection-content"
  }, content));
}
flarum.reg.add('forumaker-rolevaya', 'admin/components/settings/AdminSection', { Section: Section, });