import TagPickerField from './TagPickerField';
/**
 * "Теги" section: which flarum/tags tag each part of the Зал Славы reads
 * from. Each field opens flarum/tags' own TagSelectionModal instead of a
 * free-text slug input, so the admin can't typo a slug that doesn't exist.
 *
 * Called directly as TagsSection(attrs), not used as a JSX tag — see
 * PerkPreviewCard.tsx for why.
 */
export default function TagsSection(attrs) {
  const loaded = attrs.loaded,
    tagCharacters = attrs.tagCharacters,
    tagCharactersTag = attrs.tagCharactersTag,
    tagRole = attrs.tagRole,
    tagRoleTag = attrs.tagRoleTag,
    tagEpisodes = attrs.tagEpisodes,
    tagEpisodesTag = attrs.tagEpisodesTag,
    arenaTagSlug = attrs.arenaTagSlug,
    arenaTag = attrs.arenaTag,
    onPickCharacters = attrs.onPickCharacters,
    onPickRole = attrs.onPickRole,
    onPickEpisodes = attrs.onPickEpisodes,
    onPickArena = attrs.onPickArena;
  return m("div", {
    className: "RolevayaAdminPanel"
  }, TagPickerField({
    label: 'Тег анкет',
    slug: tagCharacters,
    tag: tagCharactersTag,
    loaded,
    onPick: onPickCharacters
  }), TagPickerField({
    label: 'Тег ролевых тем',
    slug: tagRole,
    tag: tagRoleTag,
    loaded,
    onPick: onPickRole
  }), TagPickerField({
    label: 'Тег эпизодов',
    slug: tagEpisodes,
    tag: tagEpisodesTag,
    loaded,
    onPick: onPickEpisodes
  }), TagPickerField({
    label: 'Тег арены',
    help: 'Используется для ссылки «На Арену» в виджете на главной',
    slug: arenaTagSlug,
    tag: arenaTag,
    loaded,
    onPick: onPickArena
  }));
}
flarum.reg.add('forumaker-rolevaya', 'admin/components/settings/TagsSection', TagsSection);